namespace Slic3r::GUI::JusPrin::PrinterSetup {

enum class FlowState { Initial, Recognizing, Recognized, Ambiguous, Error, Complete };

class PrinterSetupController
{
public:
    using ApplyFn = std::function<bool(const PrinterCandidate&, std::string&)>;

    PrinterSetupController(PrinterCatalog catalog, std::unique_ptr<IPrinterRecognitionService> recognition,
                           ApplyFn apply);
    ~PrinterSetupController();

    FlowState state() const { return m_state; }
    const PrinterEvidence& evidence() const { return m_evidence; }
    const std::vector<const PrinterCandidate*>& candidates() const { return m_candidates; }
    const std::string& evidence_summary() const { return m_evidence_summary; }
    const std::string& assumption() const { return m_assumption; }
    const std::string& error() const { return m_error; }
    bool retryable() const { return m_retryable; }
    const PrinterCatalog& catalog() const { return m_catalog; }

    bool recognize(PrinterEvidence evidence);
    void poll();
    bool use_discovered(const DiscoveredPrinter& printer);
    bool choose(const std::string& candidate_id);
    bool confirm();
    void start_over();

private:
    void accept(const RecognitionEvent& event);

    PrinterCatalog m_catalog;
    std::unique_ptr<IPrinterRecognitionService> m_recognition;
    ApplyFn m_apply;
    FlowState m_state{FlowState::Initial};
    PrinterEvidence m_evidence;
    std::vector<const PrinterCandidate*> m_candidates;
    std::set<std::string> m_allowed_candidate_ids;
    std::string m_evidence_summary;
    std::string m_assumption;
    std::string m_error;
    bool m_retryable{false};
    std::uint64_t m_generation{0};
};

} // namespace Slic3r::GUI::JusPrin::PrinterSetup
#include "ShellRecipes.hpp"

#include "slic3r/GUI/Widgets/Button.hpp"

#include <wx/stattext.h>
#include <wx/textctrl.h>

namespace Slic3r::GUI::JusPrin {

void style_label(wxStaticText& label, const ShellTheme& theme, TextRole role, const wxColour& foreground)
{
    label.SetFont(theme.font(role));
    label.SetForegroundColour(foreground);
}

void style_text_field(wxTextCtrl& field, const ShellTheme& theme, const ShellPalette& palette)
{
    field.SetFont(theme.font(TextRole::Body));
    field.SetBackgroundColour(palette.surface_canvas);
    field.SetForegroundColour(palette.text_primary);
}

void style_button(Button& button, const ShellTheme& theme, const ShellPalette& palette, const ButtonRecipe& recipe)
{
    // A recipe names either a fixed size or a minimum; Button has one
    // minimum-size slot, so the fixed size is applied as that minimum. A
    // dimension the recipe leaves out stays unconstrained.
    const int width  = recipe.min_width  > 0 ? recipe.min_width  : recipe.width;
    const int height = recipe.min_height > 0 ? recipe.min_height : recipe.height;
    button.SetMinSize(button.FromDIP(wxSize(width > 0 ? width : wxDefaultCoord, height > 0 ? height : wxDefaultCoord)));
    if (recipe.padding_x > 0 || recipe.padding_y > 0)
        button.SetPaddingSize(button.FromDIP(wxSize(recipe.padding_x, recipe.padding_y)));
    button.SetCornerRadius(button.FromDIP(recipe.radius));
    if (recipe.text_role)
        button.SetFont(theme.font(*recipe.text_role));
    button.SetBorderWidth(button.FromDIP(1));

    // The same state tables Button::SetStyle builds, ordered so the more
    // specific state is matched first, with focus drawn as a border rather
    // than as hover.
    StateColor background(
        std::pair(palette.action_disabled,          int(StateColor::Disabled)),
        std::pair(palette.action_secondary_pressed, int(StateColor::Pressed)),
        std::pair(palette.action_secondary_hover,   int(StateColor::Hovered)),
        std::pair(palette.action_secondary,         int(StateColor::Normal)));
    background.setTakeFocusedAsHovered(false);
    button.SetBackgroundColor(background);

    StateColor border(
        std::pair(palette.action_disabled,         int(StateColor::Disabled)),
        std::pair(palette.border_focus,            int(StateColor::Focused)),
        std::pair(palette.action_secondary_border, int(StateColor::Normal)));
    border.setTakeFocusedAsHovered(false);
    button.SetBorderColor(border);

    button.SetTextColor(StateColor(
        std::pair(palette.action_disabled_text,   int(StateColor::Disabled)),
        std::pair(palette.action_secondary_text,  int(StateColor::Normal))));
}

void style_primary_button(Button& button, const ShellTheme& theme, const ShellPalette& palette,
                          const ButtonRecipe& recipe)
{
    style_button(button, theme, palette, recipe);
    StateColor background(
        std::pair(palette.action_disabled,         int(StateColor::Disabled)),
        std::pair(palette.action_primary_pressed,  int(StateColor::Pressed)),
        std::pair(palette.action_primary_hover,    int(StateColor::Hovered)),
        std::pair(palette.action_primary,          int(StateColor::Normal)));
    background.setTakeFocusedAsHovered(false);
    button.SetBackgroundColor(background);
    StateColor border(
        std::pair(palette.action_disabled, int(StateColor::Disabled)),
        std::pair(palette.border_focus,    int(StateColor::Focused)),
        std::pair(palette.action_primary,  int(StateColor::Normal)));
    border.setTakeFocusedAsHovered(false);
    button.SetBorderColor(border);
    button.SetTextColor(StateColor(
        std::pair(palette.action_disabled_text, int(StateColor::Disabled)),
        std::pair(palette.action_primary_text,  int(StateColor::Normal))));
}

} // namespace Slic3r::GUI::JusPrin
#pragma once

// The three ways the shell dresses a stock control from the theme: a label, a
// text field, and an OrcaSlicer Button. Widgets the shell paints itself
// (HeaderButton, the swatch cells) read ShellTheme directly; these recipes
// exist so a wxStaticText or a Button never carries a hand-typed font, radius
// or colour of its own.

#include "ShellTheme.hpp"

class Button;
class wxColour;
class wxStaticText;
class wxTextCtrl;

namespace Slic3r::GUI::JusPrin {

// Font from the role, foreground as given: the caller names the colour because
// the same role reads in text_primary, text_secondary or a status colour.
void style_label(wxStaticText& label, const ShellTheme& theme, TextRole role, const wxColour& foreground);

// Body font on the canvas surface in the primary text colour.
void style_text_field(wxTextCtrl& field, const ShellTheme& theme, const ShellPalette& palette);

// Size, padding, radius and font from one of the component.button recipes;
// colours from the palette's secondary action. This is the fork's counterpart
// to Button::SetStyle(ButtonStyle::Regular, type), built from tokens instead
// of the teal tables.
void style_button(Button& button, const ShellTheme& theme, const ShellPalette& palette, const ButtonRecipe& recipe);

// The same geometry recipe with the semantic primary action state table.
void style_primary_button(Button& button, const ShellTheme& theme, const ShellPalette& palette,
                          const ButtonRecipe& recipe);

} // namespace Slic3r::GUI::JusPrin

