constexpr std::size_t kMaximumPhotoBytes = 10u * 1024u * 1024u;

class RoundedPanel final : public wxPanel
{
public:
    RoundedPanel(wxWindow* parent, const wxColour& fill, int radius, const wxSize& size)
        : wxPanel(parent, wxID_ANY, wxDefaultPosition, size, wxBORDER_NONE), m_fill(fill), m_radius(radius)
    {
        SetBackgroundStyle(wxBG_STYLE_PAINT);
        Bind(wxEVT_PAINT, [this](wxPaintEvent&) {
            wxAutoBufferedPaintDC dc(this);
            dc.SetBackground(wxBrush(GetParent()->GetBackgroundColour()));
            dc.Clear();
            dc.SetPen(*wxTRANSPARENT_PEN);
            dc.SetBrush(wxBrush(m_fill));
            dc.DrawRoundedRectangle(GetClientRect(), FromDIP(m_radius));
        });
    }
private:
    wxColour m_fill;
    int m_radius;
};

class PhotoDropTarget final : public wxFileDropTarget
{
public:
    explicit PhotoDropTarget(std::function<bool(const wxString&)> accept) : m_accept(std::move(accept)) {}
    bool OnDropFiles(wxCoord, wxCoord, const wxArrayString& filenames) override
    {
        return filenames.size() == 1 && m_accept(filenames.front());
    }
private:
    std::function<bool(const wxString&)> m_accept;
};

std::string mime_for(const wxString& path)
{
    const wxString extension = wxFileName(path).GetExt().Lower();
    if (extension == "png") return "image/png";
    if (extension == "jpg" || extension == "jpeg") return "image/jpeg";
    if (extension == "webp") return "image/webp";
    return {};
}

} // namespace

PrinterSetupDialog::PrinterSetupDialog(wxWindow* parent, const ShellTheme& theme, bool dark,
                                       std::unique_ptr<PrinterSetupController> controller,
                                       std::vector<DiscoveredPrinter> discovered)
    : DPIDialog(parent, wxID_ANY, _L("Add a printer"), wxDefaultPosition, wxDefaultSize,
                wxDEFAULT_DIALOG_STYLE | wxRESIZE_BORDER),
      m_theme(theme), m_palette(theme.palette(dark)), m_controller(std::move(controller)),
      m_discovered(std::move(discovered)), m_timer(this)
{
    SetBackgroundColour(m_palette.surface_raised);
    SetMinSize(FromDIP(wxSize(m_theme.metrics().printer_setup.dialog_width, -1)));
    m_root = new wxBoxSizer(wxVERTICAL);
    SetSizer(m_root);
    Bind(wxEVT_TIMER, &PrinterSetupDialog::on_timer, this);
    Bind(wxEVT_CLOSE_WINDOW, [this](wxCloseEvent&) { EndModal(wxID_CANCEL); });
    Bind(wxEVT_CHAR_HOOK, [this](wxKeyEvent& event) {
        if (event.GetKeyCode() == WXK_ESCAPE)
            EndModal(wxID_CANCEL);
        else
            event.Skip();
    });
    rebuild();
}

PrinterSetupDialog::~PrinterSetupDialog() { m_timer.Stop(); }

void PrinterSetupDialog::on_dpi_changed(const wxRect&) { rebuild(); }

wxStaticText* PrinterSetupDialog::label(wxWindow* parent, const wxString& text, TextRole role, const wxColour& color)
{
    auto* result = new wxStaticText(parent, wxID_ANY, text);
    style_label(*result, m_theme, role, color);
    result->Wrap(FromDIP(m_theme.metrics().printer_setup.dialog_width - 2 * m_theme.metrics().space_8));
    return result;
}

Button* PrinterSetupDialog::button(wxWindow* parent, const wxString& text, bool primary,
                                   std::function<void()> invoke)
{
    auto* result = new Button(parent, text);
    result->SetName(text);
    result->SetToolTip(text);
    if (primary) style_primary_button(*result, m_theme, m_palette, m_theme.metrics().button.primary);
    else style_button(*result, m_theme, m_palette, m_theme.metrics().button.secondary);
    result->Bind(wxEVT_BUTTON, [invoke = std::move(invoke)](wxCommandEvent&) { invoke(); });
    return result;
}

void PrinterSetupDialog::rebuild()
{
    m_description = nullptr;
    m_root->Clear(true);
    const auto& metrics = m_theme.metrics();
    auto* content = new wxBoxSizer(wxVERTICAL);
    content->Add(label(this, _L("Add a printer"), TextRole::PageTitle, m_palette.text_primary), 0, wxBOTTOM,
                 FromDIP(metrics.space_4));
    switch (m_controller->state()) {
    case FlowState::Initial: build_initial(*content); break;
    case FlowState::Recognizing: build_recognizing(*content); break;
    case FlowState::Recognized: build_recognized(*content); break;
    case FlowState::Ambiguous: build_ambiguous(*content); break;
    case FlowState::Error: build_error(*content); break;
    case FlowState::Complete: EndModal(wxID_OK); return;
    }
    m_root->Add(content, 1, wxEXPAND | wxALL, FromDIP(metrics.space_8));
    Layout();
    Fit();
    SetSize(wxSize(FromDIP(metrics.printer_setup.dialog_width), GetSize().y));
    CentreOnParent();
}

void PrinterSetupDialog::build_initial(wxBoxSizer& content)
{
    const auto& metrics = m_theme.metrics();
    content.Add(label(this, _L("Tell JusPrin what printer you have. A model name, a photo, or a printer found on your network is enough to start."),
                      TextRole::Body, m_palette.text_secondary), 0, wxEXPAND | wxBOTTOM, FromDIP(metrics.space_4));
    content.Add(label(this, _L("What printer do you have?"), TextRole::BodyBold, m_palette.text_primary),
                0, wxEXPAND | wxBOTTOM, FromDIP(metrics.space_2));
    m_description = new wxTextCtrl(this, wxID_ANY, wxString::FromUTF8(m_draft.description), wxDefaultPosition,
                                   wxDefaultSize, wxTE_MULTILINE);
    style_text_field(*m_description, m_theme, m_palette);
    m_description->SetHint(_L("For example: Bambu Lab A1 mini, or Ender 3 with a 0.4 mm nozzle"));
    content.Add(m_description, 0, wxEXPAND | wxBOTTOM, FromDIP(metrics.space_4));

    auto* photo = new RoundedPanel(this, m_palette.surface_subtle, metrics.printer_setup.radius,
                                   wxSize(-1, FromDIP(metrics.printer_setup.photo_drop_height)));
    photo->SetBackgroundColour(m_palette.surface_subtle);
    auto* photo_sizer = new wxBoxSizer(wxVERTICAL);
    const wxString photo_text = m_draft.image_name.empty()
        ? _L("Drop or choose a photo of the printer, nameplate, or box")
        : wxString::Format(_L("Photo: %s"), wxString::FromUTF8(m_draft.image_name));
    photo_sizer->AddStretchSpacer();
    photo_sizer->Add(label(photo, photo_text, TextRole::Body, m_palette.text_secondary), 0, wxALIGN_CENTER);
    photo_sizer->AddStretchSpacer();
    photo->SetSizer(photo_sizer);
    photo->SetDropTarget(new PhotoDropTarget([this](const wxString& path) {
        const bool accepted = load_photo(path);
        rebuild();
        return accepted;
    }));
    photo->Bind(wxEVT_LEFT_DOWN, [this](wxMouseEvent&) { choose_photo(); });
    content.Add(photo, 0, wxEXPAND | wxBOTTOM, FromDIP(metrics.space_6));
    if (!m_photo_error.empty())
        content.Add(label(this, m_photo_error, TextRole::BodySmall, m_palette.status_danger),
                    0, wxEXPAND | wxBOTTOM, FromDIP(metrics.space_3));

    content.Add(label(this, _L("FOUND ON YOUR NETWORK"), TextRole::MetadataBold, m_palette.text_secondary),
                0, wxBOTTOM, FromDIP(metrics.space_2));
    if (m_discovered.empty()) {
        content.Add(label(this, _L("No supported printers found yet."), TextRole::BodySmall, m_palette.text_secondary),
                    0, wxBOTTOM, FromDIP(metrics.space_4));
    } else {
        for (const DiscoveredPrinter& printer : m_discovered) {
            auto* row = new wxBoxSizer(wxHORIZONTAL);
            auto* details = new wxBoxSizer(wxVERTICAL);
            details->Add(label(this, wxString::FromUTF8(printer.name), TextRole::BodyBold, m_palette.text_primary));
            details->Add(label(this, wxString::FromUTF8(printer.stable_id), TextRole::Metadata, m_palette.text_secondary));
            const wxString availability = printer.connected
                ? wxString::Format(_L("Connected · %s"), wxString::FromUTF8(printer.connection))
                : _L("Offline");
            details->Add(label(this, availability, TextRole::Metadata, m_palette.text_secondary));
            row->Add(details, 1, wxALIGN_CENTER_VERTICAL);
            row->Add(button(this, _L("Use this"), false, [this, printer] {
                m_controller->use_discovered(printer);
                rebuild();
            }), 0, wxALIGN_CENTER_VERTICAL);
            content.Add(row, 0, wxEXPAND | wxBOTTOM, FromDIP(metrics.space_2));
        }
    }

    auto* footer = new wxBoxSizer(wxHORIZONTAL);
    auto* manual = new wxHyperlinkCtrl(this, wxID_ANY, _L("Prefer a big list? Set it up myself"), "manual");
    manual->SetFont(m_theme.font(TextRole::BodySmall));
    manual->SetNormalColour(m_palette.text_secondary);
    manual->SetHoverColour(m_palette.action_primary_hover);
    manual->Bind(wxEVT_HYPERLINK, [this](wxHyperlinkEvent&) { open_manual_setup(); });
    footer->Add(manual, 1, wxALIGN_CENTER_VERTICAL);
    auto* next = button(this, _L("Next"), true, [this] { submit(); });
    next->Enable(!m_draft.description.empty() || !m_draft.image_bytes.empty());
    m_description->Bind(wxEVT_TEXT, [this, next](wxCommandEvent&) {
        next->Enable(!m_description->GetValue().empty() || !m_draft.image_bytes.empty());
    });
    footer->Add(next, 0, wxALIGN_CENTER_VERTICAL);
    content.Add(footer, 0, wxEXPAND | wxTOP, FromDIP(metrics.space_4));
}

void PrinterSetupDialog::build_recognizing(wxBoxSizer& content)
{
    content.Add(label(this, _L("Looking for a matching printer profile…"), TextRole::Body,
                      m_palette.text_secondary), 0, wxEXPAND | wxBOTTOM, FromDIP(m_theme.metrics().space_6));
    content.Add(button(this, _L("Cancel"), false, [this] {
        m_controller->start_over();
        m_timer.Stop();
        rebuild();
    }), 0, wxALIGN_RIGHT);
}

wxPanel* PrinterSetupDialog::candidate_card(wxWindow* parent, const PrinterCandidate& candidate, bool compact,
                                            const wxString& action, std::function<void()> invoke)
{
    const auto& metrics = m_theme.metrics();
    auto* card = new RoundedPanel(parent, m_palette.surface_subtle, metrics.printer_setup.radius,
                                  wxSize(-1, FromDIP(metrics.printer_setup.candidate_min_height)));
    card->SetBackgroundColour(m_palette.surface_subtle);
    auto* row = new wxBoxSizer(wxHORIZONTAL);
    if (!candidate.artwork_path.empty()) {
        wxImage image(wxString::FromUTF8(candidate.artwork_path));
        if (image.IsOk()) {
            const int size = card->FromDIP(metrics.printer_setup.artwork_size);
            image.Rescale(size, size, wxIMAGE_QUALITY_HIGH);
            row->Add(new wxStaticBitmap(card, wxID_ANY, wxBitmap(image)), 0, wxALL | wxALIGN_CENTER_VERTICAL,
                     card->FromDIP(metrics.space_3));
        }
    }
    auto* details = new wxBoxSizer(wxVERTICAL);
    details->Add(label(card, wxString::FromUTF8(candidate.model_name), TextRole::BodyBold, m_palette.text_primary));
    details->Add(label(card, wxString::Format(_L("%s mm nozzle"), wxString::FromUTF8(candidate.variant)),
                       TextRole::BodySmall, m_palette.text_secondary));
    if (!candidate.build_volume.empty())
        details->Add(label(card, wxString::FromUTF8(candidate.build_volume), TextRole::BodySmall, m_palette.text_secondary));
    if (!compact && !candidate.default_plate.empty())
        details->Add(label(card, wxString::Format(_L("Starts with %s"), wxString::FromUTF8(candidate.default_plate)),
                           TextRole::BodySmall, m_palette.text_secondary));
    if (!compact && !candidate.default_material.empty())
        details->Add(label(card, wxString::Format(_L("Starts with %s"), wxString::FromUTF8(candidate.default_material)),
                           TextRole::BodySmall, m_palette.text_secondary));
    row->Add(details, 1, wxALL | wxALIGN_CENTER_VERTICAL, card->FromDIP(metrics.space_3));
    if (!action.empty())
        row->Add(button(card, action, false, std::move(invoke)), 0, wxRIGHT | wxALIGN_CENTER_VERTICAL,
                 card->FromDIP(metrics.space_3));
    card->SetSizer(row);
    return card;
}

void PrinterSetupDialog::build_recognized(wxBoxSizer& content)
{
    const auto& metrics = m_theme.metrics();
    const PrinterCandidate& candidate = *m_controller->candidates().front();
    if (!m_controller->evidence_summary().empty())
        content.Add(label(this, wxString::Format("“%s”", wxString::FromUTF8(m_controller->evidence_summary())),
                          TextRole::Body, m_palette.text_secondary), 0, wxEXPAND | wxBOTTOM, FromDIP(metrics.space_4));
    content.Add(candidate_card(this, candidate, false, {}, {}), 0, wxEXPAND | wxBOTTOM, FromDIP(metrics.space_4));
    if (!m_controller->assumption().empty())
        content.Add(label(this, wxString::FromUTF8(m_controller->assumption()), TextRole::BodySmall,
                          m_palette.text_secondary), 0, wxEXPAND | wxBOTTOM, FromDIP(metrics.space_4));
    if (m_controller->evidence().discovered_device)
        content.Add(label(this,
                          wxString::Format(_L("Device ID: %s"),
                                           wxString::FromUTF8(m_controller->evidence().discovered_device->stable_id)),
                          TextRole::Metadata, m_palette.text_secondary),
                    0, wxEXPAND | wxBOTTOM, FromDIP(metrics.space_4));
    auto* correction = new wxTextCtrl(this, wxID_ANY);
    style_text_field(*correction, m_theme, m_palette);
    correction->SetHint(_L("Something different? Add a correction"));
    content.Add(correction, 0, wxEXPAND | wxBOTTOM, FromDIP(metrics.space_4));
    auto* actions = new wxBoxSizer(wxHORIZONTAL);
    actions->Add(button(this, _L("Not this one"), false, [this] { m_controller->start_over(); rebuild(); }), 1);
    actions->AddSpacer(FromDIP(metrics.space_2));
    auto* retry = button(this, _L("Try correction"), false, [this, correction] {
        m_draft = m_controller->evidence();
        m_draft.description += "\nCorrection: " + std::string(correction->GetValue().ToUTF8());
        m_controller->recognize(m_draft); m_timer.Start(50); rebuild();
    });
    retry->Enable(false);
    correction->Bind(wxEVT_TEXT, [retry, correction](wxCommandEvent&) { retry->Enable(!correction->GetValue().empty()); });
    actions->Add(retry, 0);
    actions->AddSpacer(FromDIP(metrics.space_2));
    actions->Add(button(this, _L("Add this printer"), true, [this] {
        if (m_controller->confirm()) EndModal(wxID_OK); else rebuild();
    }), 0);
    content.Add(actions, 0, wxEXPAND);
}

void PrinterSetupDialog::build_ambiguous(wxBoxSizer& content)
{
    const auto& metrics = m_theme.metrics();
    if (!m_controller->evidence_summary().empty())
        content.Add(label(this, wxString::Format("“%s”", wxString::FromUTF8(m_controller->evidence_summary())),
                          TextRole::Body, m_palette.text_secondary), 0, wxEXPAND | wxBOTTOM, FromDIP(metrics.space_3));
    content.Add(label(this, _L("Which one is yours?"), TextRole::Section, m_palette.text_primary),
                0, wxBOTTOM, FromDIP(metrics.space_3));
    for (const PrinterCandidate* candidate : m_controller->candidates())
        content.Add(candidate_card(this, *candidate, true, _L("This one"), [this, id = candidate->id] {
            m_controller->choose(id); rebuild();
        }), 0, wxEXPAND | wxBOTTOM, FromDIP(metrics.space_2));
    auto* actions = new wxBoxSizer(wxHORIZONTAL);
    actions->Add(button(this, _L("Upload a photo"), false, [this] {
        choose_photo();
        wxGetApp().CallAfter([this] {
            if (!m_draft.image_bytes.empty())
                submit();
        });
    }), 1);
    actions->AddSpacer(FromDIP(metrics.space_2));
    actions->Add(button(this, _L("Start over"), false, [this] { m_controller->start_over(); rebuild(); }), 0);
    content.Add(actions, 0, wxEXPAND | wxTOP, FromDIP(metrics.space_3));
}

void PrinterSetupDialog::build_error(wxBoxSizer& content)
{
    const auto& metrics = m_theme.metrics();
    content.Add(label(this, wxString::FromUTF8(m_controller->error()), TextRole::Body, m_palette.status_danger),
                0, wxEXPAND | wxBOTTOM, FromDIP(metrics.space_4));
    auto* actions = new wxBoxSizer(wxHORIZONTAL);
    actions->Add(button(this, _L("Set it up manually"), false, [this] { open_manual_setup(); }), 1);
    actions->AddSpacer(FromDIP(metrics.space_2));
    if (m_controller->retryable())
        actions->Add(button(this, _L("Retry"), true, [this] { submit(); }), 0);
    else
        actions->Add(button(this, _L("Start over"), true, [this] { m_controller->start_over(); rebuild(); }), 0);
    content.Add(actions, 0, wxEXPAND);
}

void PrinterSetupDialog::choose_photo()
{
    if (m_description)
        m_draft.description = std::string(m_description->GetValue().ToUTF8());
    wxFileDialog picker(this, _L("Choose a printer photo"), {}, {},
                        _L("Image files (*.png;*.jpg;*.jpeg;*.webp)|*.png;*.jpg;*.jpeg;*.webp"),
                        wxFD_OPEN | wxFD_FILE_MUST_EXIST);
    if (picker.ShowModal() == wxID_OK) {
        load_photo(picker.GetPath());
        rebuild();
    }
}

