 65	std::string mime_for(const wxString& path)
 66	{
 67	    const wxString extension = wxFileName(path).GetExt().Lower();
 68	    if (extension == "png") return "image/png";
 69	    if (extension == "jpg" || extension == "jpeg") return "image/jpeg";
 70	    if (extension == "webp") return "image/webp";
 71	    return {};
 72	}
