361	bool PrinterSetupDialog::load_photo(const wxString& path)
362	{
363	    const std::string mime = mime_for(path);
364	    if (mime.empty()) {
365	        m_photo_error = _L("Choose a PNG, JPEG, or WebP image.");
366	        return false;
367	    }
368	    std::ifstream input(std::string(path.ToUTF8()), std::ios::binary);
369	    if (!input) {
370	        m_photo_error = _L("That photo could not be read. Choose another file.");
371	        return false;
372	    }
373	    std::string bytes((std::istreambuf_iterator<char>(input)), std::istreambuf_iterator<char>());
374	    if (bytes.empty()) {
375	        m_photo_error = _L("That photo is empty. Choose another file.");
376	        return false;
377	    }
378	    if (bytes.size() > kMaximumPhotoBytes) {
379	        m_photo_error = _L("That photo is larger than 10 MB. Choose a smaller image.");
380	        return false;
381	    }
382	    wxMemoryInputStream stream(bytes.data(), bytes.size());
383	    wxImage decoded(stream);
384	    if (!decoded.IsOk()) {
385	        m_photo_error = _L("That file is not a readable image. Choose another photo.");
386	        return false;
387	    }
388	    m_draft.image_bytes = std::move(bytes);
389	    m_draft.image_mime = mime;
390	    m_draft.image_name = std::string(wxFileName(path).GetFullName().ToUTF8());
391	    m_photo_error.clear();
392	    return true;
393	}
