303	void ShellController::on_frame_destroy(wxWindowDestroyEvent& event)
304	{
305	    if (event.GetWindow() == m_frame) {
306	        m_runtime_timer.Stop();
307	        m_installed = false;
308	        m_prepare_canvas_presentation.abandon();
309	        // This controller lives in a static slot and outlives every window,
310	        // so whatever it owns that unbinds from the Plater has to go now,
311	        // while the frame's children still exist: wx sends this event from
312	        // the top-level window's destructor, before DestroyChildren. Left in
313	        // place, the slot's destructor ran ~OrcaWorkspaceAdapter against a
314	        // deleted Plater after main had returned -- an access violation at
315	        // process exit in every run that did not detach the shell by hand.
316	        // Same order as uninstall(): the pane and status row first, since
317	        // their destructors talk to persistence and the workspace, then
318	        // those two. The remaining children die with the frame.
319	        if (m_agent_pane != nullptr) {
320	            m_agent_pane->Destroy();
321	            m_agent_pane = nullptr;
322	        }
323	        if (m_status_row != nullptr) {
324	            m_status_row->Destroy();
325	            m_status_row = nullptr;
326	        }
327	        m_persistence.reset();
328	        m_workspace.reset();
329	    }
330	    event.Skip();

