 56	    } catch (const std::exception&) {
 57	        // Theme/catalog packaging failures cannot be recovered inside the
 58	        // custom flow; Orca's existing complete setup remains available.
 59	        wxGetApp().run_wizard(ConfigWizard::RR_USER, ConfigWizard::SP_PRINTERS);
 60	    }
