 32	class RoundedPanel final : public wxPanel
 33	{
 34	public:
 35	    RoundedPanel(wxWindow* parent, const wxColour& fill, int radius, const wxSize& size)
 36	        : wxPanel(parent, wxID_ANY, wxDefaultPosition, size, wxBORDER_NONE), m_fill(fill), m_radius(radius)
 37	    {
 38	        SetBackgroundStyle(wxBG_STYLE_PAINT);
 39	        Bind(wxEVT_PAINT, [this](wxPaintEvent&) {
 40	            wxAutoBufferedPaintDC dc(this);
 41	            dc.SetBackground(wxBrush(GetParent()->GetBackgroundColour()));
 42	            dc.Clear();
 43	            dc.SetPen(*wxTRANSPARENT_PEN);
 44	            dc.SetBrush(wxBrush(m_fill));
 45	            dc.DrawRoundedRectangle(GetClientRect(), FromDIP(m_radius));
 46	        });
 47	    }
 48	private:
 49	    wxColour m_fill;
 50	    int m_radius;
 51	};
