 53	class PhotoDropTarget final : public wxFileDropTarget
 54	{
 55	public:
 56	    explicit PhotoDropTarget(std::function<bool(const wxString&)> accept) : m_accept(std::move(accept)) {}
 57	    bool OnDropFiles(wxCoord, wxCoord, const wxArrayString& filenames) override
 58	    {
 59	        return filenames.size() == 1 && m_accept(filenames.front());
 60	    }
 61	private:
