123	void PrinterSetupDialog::rebuild()
124	{
125	    m_description = nullptr;
126	    m_root->Clear(true);
127	    const auto& metrics = m_theme.metrics();
128	    auto* content = new wxBoxSizer(wxVERTICAL);
129	    content->Add(label(this, _L("Add a printer"), TextRole::PageTitle, m_palette.text_primary), 0, wxBOTTOM,
130	                 FromDIP(metrics.space_4));
131	    switch (m_controller->state()) {
132	    case FlowState::Initial: build_initial(*content); break;
133	    case FlowState::Recognizing: build_recognizing(*content); break;
134	    case FlowState::Recognized: build_recognized(*content); break;
135	    case FlowState::Ambiguous: build_ambiguous(*content); break;
136	    case FlowState::Error: build_error(*content); break;
137	    case FlowState::Complete: EndModal(wxID_OK); return;
138	    }
139	    m_root->Add(content, 1, wxEXPAND | wxALL, FromDIP(metrics.space_8));
140	    Layout();
141	    Fit();
142	    SetSize(wxSize(FromDIP(metrics.printer_setup.dialog_width), GetSize().y));
143	    CentreOnParent();
144	}
