269	void PrinterSetupDialog::build_recognized(wxBoxSizer& content)
270	{
271	    const auto& metrics = m_theme.metrics();
272	    const PrinterCandidate& candidate = *m_controller->candidates().front();
273	    if (!m_controller->evidence_summary().empty())
274	        content.Add(label(this, wxString::Format("“%s”", wxString::FromUTF8(m_controller->evidence_summary())),
275	                          TextRole::Body, m_palette.text_secondary), 0, wxEXPAND | wxBOTTOM, FromDIP(metrics.space_4));
276	    content.Add(candidate_card(this, candidate, false, {}, {}), 0, wxEXPAND | wxBOTTOM, FromDIP(metrics.space_4));
277	    if (!m_controller->assumption().empty())
278	        content.Add(label(this, wxString::FromUTF8(m_controller->assumption()), TextRole::BodySmall,
279	                          m_palette.text_secondary), 0, wxEXPAND | wxBOTTOM, FromDIP(metrics.space_4));
280	    if (m_controller->evidence().discovered_device)
281	        content.Add(label(this,
282	                          wxString::Format(_L("Device ID: %s"),
283	                                           wxString::FromUTF8(m_controller->evidence().discovered_device->stable_id)),
284	                          TextRole::Metadata, m_palette.text_secondary),
285	                    0, wxEXPAND | wxBOTTOM, FromDIP(metrics.space_4));
286	    auto* correction = new wxTextCtrl(this, wxID_ANY);
287	    style_text_field(*correction, m_theme, m_palette);
288	    correction->SetHint(_L("Something different? Add a correction"));
289	    content.Add(correction, 0, wxEXPAND | wxBOTTOM, FromDIP(metrics.space_4));
290	    auto* actions = new wxBoxSizer(wxHORIZONTAL);
291	    actions->Add(button(this, _L("Not this one"), false, [this] { m_controller->start_over(); rebuild(); }), 1);
292	    actions->AddSpacer(FromDIP(metrics.space_2));
293	    auto* retry = button(this, _L("Try correction"), false, [this, correction] {
294	        m_draft = m_controller->evidence();
295	        m_draft.description += "\nCorrection: " + std::string(correction->GetValue().ToUTF8());
296	        m_controller->recognize(m_draft); m_timer.Start(50); rebuild();
297	    });
298	    retry->Enable(false);
299	    correction->Bind(wxEVT_TEXT, [retry, correction](wxCommandEvent&) { retry->Enable(!correction->GetValue().empty()); });
300	    actions->Add(retry, 0);
301	    actions->AddSpacer(FromDIP(metrics.space_2));
302	    actions->Add(button(this, _L("Add this printer"), true, [this] {
303	        if (m_controller->confirm()) EndModal(wxID_OK); else rebuild();
304	    }), 0);
305	    content.Add(actions, 0, wxEXPAND);
306	}
