396	{
397	    if (m_description) m_draft.description = std::string(m_description->GetValue().ToUTF8());
398	    else if (m_draft.description.empty()) m_draft = m_controller->evidence();
399	    m_controller->recognize(m_draft);
400	    if (m_controller->state() == FlowState::Recognizing) m_timer.Start(50);
401	    rebuild();
