 22	void show_printer_setup(wxWindow* owner, const ShellTheme& theme, bool dark, Plater& plater)
 23	{
 24	    PrinterCatalog catalog = PrinterCatalog::load(Slic3r::resources_dir());
 25	    OpenAIPrinterRecognitionConfig config;
 26	    if (wxGetApp().app_config) {
 27	        const std::string consent = wxGetApp().app_config->get("jusprin_agent", "cloud_consent");
 28	        if (consent == "true" || consent == "1")
 29	            config.api_key = Agent::load_provider_api_key("openai");
 30	        const std::string model = wxGetApp().app_config->get("jusprin_agent", "model");
 31	        if (!model.empty()) config.model = model;
 32	    }
 33	    if (const char* endpoint = std::getenv("JUSPRIN_OPENAI_ENDPOINT"); endpoint && *endpoint)
 34	        config.endpoint = endpoint;
 35	    std::unique_ptr<IPrinterRecognitionService> recognition;
 36	    if (std::getenv("JUSPRIN_PRINTER_RECOGNITION_MOCK"))
 37	        recognition = std::make_unique<DeterministicPrinterRecognition>();
 38	    else
 39	        recognition = std::make_unique<OpenAIPrinterRecognition>(std::move(config),
 40	                                                                  Agent::make_openai_http_transport());
 41	    auto apply = [&plater](const PrinterCandidate& candidate, std::string& error) {
 42	        return SetupCommands::install_and_select_printer(plater, candidate.vendor_id, candidate.model_id,
 43	                                                         candidate.variant, candidate.default_material, error);
 44	    };
 45	    auto controller = std::make_unique<PrinterSetupController>(std::move(catalog), std::move(recognition),
 46	                                                                std::move(apply));
 47	    PrinterSetupDialog dialog(owner, theme, dark, std::move(controller), discover_printers());
 48	    dialog.ShowModal();
 49	}
