#include "PrinterSetupController.hpp"

#include <algorithm>
#include <set>
#include <utility>

namespace Slic3r::GUI::JusPrin::PrinterSetup {

PrinterSetupController::PrinterSetupController(PrinterCatalog catalog,
                                               std::unique_ptr<IPrinterRecognitionService> recognition,
                                               ApplyFn apply)
    : m_catalog(std::move(catalog)), m_recognition(std::move(recognition)), m_apply(std::move(apply)) {}

PrinterSetupController::~PrinterSetupController()
{
    if (m_recognition) m_recognition->cancel();
}

bool PrinterSetupController::recognize(PrinterEvidence evidence)
{
    if (evidence.description.empty() && evidence.image_bytes.empty()) return false;
    m_evidence = std::move(evidence);
    m_candidates.clear();
    m_error.clear();
    m_retryable = false;
    ++m_generation;
    const auto choices = m_catalog.recognition_choices(m_evidence);
    m_allowed_candidate_ids.clear();
    for (const PrinterCandidate* choice : choices)
        if (choice) m_allowed_candidate_ids.insert(choice->id);
    if (!m_recognition || !m_recognition->ready()) {
        m_state = FlowState::Error;
        m_error = "Printer recognition needs the OpenAI key configured in the Agent panel. You can still use a network printer or set it up manually.";
        return false;
    }
    if (!m_recognition->start(m_generation, m_evidence, choices)) {
        m_state = FlowState::Error;
        m_error = "Printer recognition could not start.";
        m_retryable = true;
        return false;
    }
    m_state = FlowState::Recognizing;
    return true;
}

void PrinterSetupController::poll()
{
    if (!m_recognition) return;
    while (auto event = m_recognition->poll()) accept(*event);
}

void PrinterSetupController::accept(const RecognitionEvent& event)
{
    if (event.generation != m_generation || m_state != FlowState::Recognizing) return;
    if (event.error) {
        m_state = FlowState::Error;
        m_error = event.error->message;
        m_retryable = event.error->retryable;
        return;
    }
    if (!event.result) return;
    std::set<std::string> seen;
    for (const std::string& id : event.result->candidate_ids) {
        if (!seen.insert(id).second) continue;
        if (!m_allowed_candidate_ids.count(id)) continue;
        if (const PrinterCandidate* candidate = m_catalog.find(id)) m_candidates.push_back(candidate);
    }
    m_evidence_summary = event.result->evidence_summary;
    m_assumption = event.result->assumption;
    if (event.result->disposition == RecognitionDisposition::Recognized && m_candidates.size() == 1)
        m_state = FlowState::Recognized;
    else if (event.result->disposition == RecognitionDisposition::Ambiguous && m_candidates.size() >= 2)
        m_state = FlowState::Ambiguous;
    else {
        m_state = FlowState::Error;
        m_error = "That evidence did not match a supported printer profile. Add a clearer description or photo, or set it up manually.";
    }
}

bool PrinterSetupController::use_discovered(const DiscoveredPrinter& printer)
{
    const PrinterCandidate* candidate = m_catalog.find_device_model(printer.device_model_id);
    if (!candidate) {
        m_state = FlowState::Error;
        m_error = "The network printer was found, but its model does not match a supported local profile.";
        return false;
    }
    if (m_recognition) m_recognition->cancel();
    ++m_generation;
    m_evidence = {};
    m_evidence.discovered_device = printer;
    m_allowed_candidate_ids.clear();
    m_candidates = {candidate};
    m_evidence_summary = printer.name;
    m_assumption = printer.connection.empty() ? "Found on the local network."
                                               : "Connected · " + printer.connection;
    m_state = FlowState::Recognized;
    return true;
}

bool PrinterSetupController::choose(const std::string& candidate_id)
{
    if (m_state != FlowState::Ambiguous) return false;
    const auto found = std::find_if(m_candidates.begin(), m_candidates.end(), [&](const PrinterCandidate* candidate) {
        return candidate && candidate->id == candidate_id;
    });
    if (found == m_candidates.end()) return false;
    const PrinterCandidate* candidate = *found;
    m_candidates = {candidate};
    m_state = FlowState::Recognized;
    return true;
}

bool PrinterSetupController::confirm()
{
    if (m_state != FlowState::Recognized || m_candidates.size() != 1 || !m_apply) return false;
    std::string error;
    if (!m_apply(*m_candidates.front(), error)) {
        m_error = error.empty() ? "The printer setup could not be applied. Your previous setup is unchanged." : error;
        m_state = FlowState::Error;
        m_retryable = true;
        return false;
    }
    m_state = FlowState::Complete;
    return true;
}

void PrinterSetupController::start_over()
{
    if (m_recognition) m_recognition->cancel();
    ++m_generation;
    m_state = FlowState::Initial;
    m_evidence = {};
    m_candidates.clear();
    m_allowed_candidate_ids.clear();
    m_evidence_summary.clear();
    m_assumption.clear();
    m_error.clear();
    m_retryable = false;
}

} // namespace Slic3r::GUI::JusPrin::PrinterSetup
#include "PrinterCatalog.hpp"

#include <nlohmann/json.hpp>

#include <algorithm>
#include <cctype>
#include <cmath>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <map>
#include <set>
#include <sstream>
#include <stdexcept>

namespace Slic3r::GUI::JusPrin::PrinterSetup {

namespace fs = std::filesystem;
using nlohmann::json;

namespace {

json read_json(const fs::path& path)
{
    std::ifstream input(path);
    if (!input)
        throw std::runtime_error("Could not read printer profile: " + path.string());
    return json::parse(input);
}

std::vector<std::string> split(const std::string& value, char delimiter)
{
    std::vector<std::string> result;
    std::istringstream input(value);
    std::string part;
    while (std::getline(input, part, delimiter))
        if (!part.empty()) result.push_back(part);
    return result;
}

std::string lower(std::string value)
{
    std::transform(value.begin(), value.end(), value.begin(),
                   [](unsigned char c) { return char(std::tolower(c)); });
    return value;
}

std::set<std::string> words(const std::string& value)
{
    std::set<std::string> result;
    std::string word;
    for (unsigned char c : lower(value)) {
        if (std::isalnum(c)) word.push_back(char(c));
        else if (word.size() > 1) { result.insert(word); word.clear(); }
        else word.clear();
    }
    if (word.size() > 1) result.insert(word);
    return result;
}

std::string first_string(const json& value)
{
    if (value.is_string()) return value.get<std::string>();
    if (value.is_array() && !value.empty() && value.front().is_string())
        return value.front().get<std::string>();
    return {};
}

json resolve_machine(const std::string& name, const std::map<std::string, json>& machines,
                     std::set<std::string>& visiting)
{
    const auto found = machines.find(name);
    if (found == machines.end() || !visiting.insert(name).second)
        return json::object();
    json resolved = json::object();
    const std::string parent = found->second.value("inherits", "");
    if (!parent.empty())
        resolved = resolve_machine(parent, machines, visiting);
    for (const auto& item : found->second.items())
        resolved[item.key()] = item.value();
    visiting.erase(name);
    return resolved;
}

std::string build_volume(const json& machine)
{
    const auto area = machine.value("printable_area", json::array());
    double min_x = 0., min_y = 0., max_x = 0., max_y = 0.;
    bool first = true;
    for (const auto& point : area) {
        if (!point.is_string()) continue;
        const auto values = split(point.get<std::string>(), 'x');
        if (values.size() != 2) continue;
        try {
            const double x = std::stod(values[0]);
            const double y = std::stod(values[1]);
            if (first) { min_x = max_x = x; min_y = max_y = y; first = false; }
            else { min_x = std::min(min_x, x); max_x = std::max(max_x, x);
                   min_y = std::min(min_y, y); max_y = std::max(max_y, y); }
        } catch (const std::exception&) {}
    }
    if (first) return {};
    const std::string height = first_string(machine.value("printable_height", json()));
    if (height.empty()) return {};
    auto clean = [](double value) {
        std::ostringstream out;
        out << std::fixed << std::setprecision(value == std::floor(value) ? 0 : 1) << value;
        return out.str();
    };
    return clean(max_x - min_x) + " × " + clean(max_y - min_y) + " × " + height + " mm";
}

} // namespace

PrinterCatalog::PrinterCatalog(std::vector<PrinterCandidate> candidates) : m_candidates(std::move(candidates)) {}

PrinterCatalog PrinterCatalog::load(const std::string& resources_directory)
{
    const fs::path profiles = fs::path(resources_directory) / "profiles";
    std::vector<PrinterCandidate> candidates;
    for (const fs::directory_entry& vendor_entry : fs::directory_iterator(profiles)) {
        if (!vendor_entry.is_regular_file() || vendor_entry.path().extension() != ".json") continue;
        const std::string vendor_id = vendor_entry.path().stem().string();
        const json index = read_json(vendor_entry.path());
        if (!index.contains("machine_model_list") || !index.contains("machine_list")) continue;
        const std::string vendor_name = index.value("name", vendor_id);
        const fs::path vendor_dir = profiles / vendor_id;

        std::map<std::string, json> machines;
        for (const auto& entry : index["machine_list"]) {
            const std::string name = entry.value("name", "");
            const std::string sub_path = entry.value("sub_path", "");
            if (!name.empty() && !sub_path.empty()) machines.emplace(name, read_json(vendor_dir / sub_path));
        }

        for (const auto& entry : index["machine_model_list"]) {
            const std::string sub_path = entry.value("sub_path", "");
            if (sub_path.empty()) continue;
            const json model = read_json(vendor_dir / sub_path);
            const std::string model_name = model.value("name", entry.value("name", ""));
            const std::string model_id = model_name;
            const std::string device_model = model.value("model_id", "");
            const auto variants = split(first_string(model.value("nozzle_diameter", json())), ';');
            const auto materials = split(first_string(model.value("default_materials", json())), ';');
            const std::string plate = first_string(model.value("default_bed_type", json()));
            fs::path artwork = vendor_dir / (model_name + "_cover.png");
            if (!fs::exists(artwork)) artwork.clear();

            for (const std::string& variant : variants) {
                const std::string preset_name = model_name + " " + variant + " nozzle";
                std::set<std::string> visiting;
                const json machine = resolve_machine(preset_name, machines, visiting);
                if (machine.empty()) continue; // not an installable variant
                PrinterCandidate candidate;
                candidate.id = "printer-" + std::to_string(candidates.size());
                candidate.vendor_id = vendor_id;
                candidate.vendor_name = vendor_name;
                candidate.model_id = model_id;
                candidate.model_name = model_name;
                candidate.device_model_id = device_model;
                candidate.variant = variant;
                candidate.preset_name = preset_name;
                candidate.build_volume = build_volume(machine);
                candidate.default_material = !materials.empty() ? materials.front()
                    : first_string(machine.value("default_filament_profile", json()));
                candidate.default_plate = plate;
                candidate.artwork_path = artwork.string();
                candidates.push_back(std::move(candidate));
            }
        }
    }
    if (candidates.empty())
        throw std::runtime_error("No installable printer profiles were found.");
    return PrinterCatalog(std::move(candidates));
}

const PrinterCandidate* PrinterCatalog::find(const std::string& id) const
{
    const auto found = std::find_if(m_candidates.begin(), m_candidates.end(),
                                    [&](const PrinterCandidate& item) { return item.id == id; });
    return found == m_candidates.end() ? nullptr : &*found;
}

const PrinterCandidate* PrinterCatalog::find_device_model(const std::string& device_model_id) const
{
    const auto found = std::find_if(m_candidates.begin(), m_candidates.end(), [&](const PrinterCandidate& item) {
        return !device_model_id.empty() && item.device_model_id == device_model_id && item.variant == "0.4";
    });
    if (found != m_candidates.end()) return &*found;
    const auto any = std::find_if(m_candidates.begin(), m_candidates.end(), [&](const PrinterCandidate& item) {
        return !device_model_id.empty() && item.device_model_id == device_model_id;
    });
    return any == m_candidates.end() ? nullptr : &*any;
}

std::vector<const PrinterCandidate*> PrinterCatalog::recognition_choices(const PrinterEvidence& evidence) const
{
    struct Scored { const PrinterCandidate* candidate; int score; };
    const auto evidence_words = words(evidence.description);
    std::vector<Scored> scored;
    scored.reserve(m_candidates.size());
    for (const PrinterCandidate& candidate : m_candidates) {
        int score = 0;
        const auto candidate_words = words(candidate.vendor_name + " " + candidate.model_name + " " + candidate.variant);
        for (const std::string& word : evidence_words)
            if (candidate_words.count(word)) score += word.size() >= 4 ? 3 : 1;
        if (!evidence.description.empty() && lower(evidence.description).find(lower(candidate.model_name)) != std::string::npos)
            score += 20;
        scored.push_back({&candidate, score});
    }
    std::stable_sort(scored.begin(), scored.end(), [](const Scored& a, const Scored& b) { return a.score > b.score; });

    std::vector<const PrinterCandidate*> result;
    std::set<std::string> models;
    const bool has_text_match = !scored.empty() && scored.front().score > 0;
    for (const Scored& item : scored) {
        if (has_text_match) {
            if (item.score == 0 || result.size() >= 60) break;
            result.push_back(item.candidate);
        } else if (models.insert(item.candidate->vendor_id + "\n" + item.candidate->model_id).second) {
            result.push_back(item.candidate);
            if (result.size() >= 400) break;
        }
    }
    return result;
}

} // namespace Slic3r::GUI::JusPrin::PrinterSetup

