    void SetCenter(bool isCenter);

    void SetVertical(bool vertical = true);

    void Rescale();

protected:
#ifdef __WIN32__
    WXLRESULT MSWWindowProc(WXUINT nMsg, WXWPARAM wParam, WXLPARAM lParam) override;
