    m_finish_text->SetForegroundColour(wxColour(255, 255, 255, 255));
    text_sizer->Add(m_finish_text, 0, wxALIGN_LEFT | wxALIGN_CENTER_VERTICAL | wxALL, 0);
    text_sizer->AddSpacer(FromDIP(20));
